<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {api,type Schema,type Table,type Trace,type Simulation,type Wire,exportText} from '../api';
import type {CaseSpec} from '../generated/CaseSpec';
import type {CaseGrade} from '../generated/CaseGrade';
import type {RepairValidation} from '../generated/RepairValidation';
import {useLab} from '../store';
import SqlEditor from '../components/SqlEditor.vue';
import ResultTable from '../components/ResultTable.vue';
import TraceView from '../components/TraceView.vue';
import SchedulePlayback from '../components/SchedulePlayback.vue';
import PredictionCheckpoint from '../components/PredictionCheckpoint.vue';
import {markdownTable} from '../report';
defineProps<{theme:string}>();const emit=defineEmits<{connect:[]}>();const lab=useLab();
const showPrediction=ref(true);const templates=ref('');const spec=ref<Wire<CaseSpec>>();const schema=ref<Schema>({engine:'SQLite',version:0,relations:[],routines:[]});const selected=ref('capacity');const p=computed(()=>lab.workspace!.case_progress);const task=computed(()=>spec.value?.tasks.find(t=>t.id===selected.value));
const channels=['case-query','case-grade','case-trace','case-repair','case-close','case-simulation'];
const result=ref<{table:Table,snapshot:string}>();const executedSql=ref('');const grading=ref<Wire<CaseGrade>>();const trace=ref<Trace>();const simulation=ref<{source:string,simulation:Simulation}>();const repair=ref<Wire<RepairValidation>>();const strategy=ref('naive');const actual=ref<number>();const counter=ref<number>();const cause=ref('');const stale=computed(()=>!!spec.value&&p.value.version!==spec.value.version);
function changed(){p.value.closed=false;lab.markDirty();}
const answer=computed({get:()=>p.value.answers[selected.value]??task.value?.starter??'',set:(v:string)=>{p.value.answers[selected.value]=v;clear();changed();}});
function args(){return{case_id:spec.value!.id,version:spec.value!.version,seed:p.value.seed,task:selected.value};}
function clear(){lab.invalidateJobs(channels);result.value=undefined;grading.value=undefined;trace.value=undefined;repair.value=undefined;}
function fresh(){if(!spec.value)return;p.value.version=spec.value.version;p.value.completed=[];p.value.answers={};p.value.model_strategy='';p.value.mysql_strategy='';p.value.cause='';clear();changed();}
onMounted(async()=>{try{spec.value=await api<Wire<CaseSpec>>('case_catalog');if(!p.value.version)p.value.version=spec.value.version;selected.value=p.value.task||'capacity';schema.value=await api<Schema>('case_schema',args());templates.value=await api<string>('case_templates',args());}catch(e){lab.fail(e)}});
watch(selected,()=>{showPrediction.value=true;clear();simulation.value=undefined;actual.value=undefined;counter.value=undefined;cause.value='';if(selected.value==='reproduce'&&p.value.answers.reproduce){try{const a=JSON.parse(p.value.answers.reproduce);actual.value=a.actual;counter.value=a.counter;cause.value=a.cause}catch{/* keep invalid saved answer editable */}}});
onBeforeUnmount(()=>lab.invalidateJobs(channels));
async function run(){const sql=answer.value;const r=await lab.run<{table:Table,snapshot:string}>('case-query','case_query',{...args(),sql});if(r){result.value=r;executedSql.value=sql;}}
async function visualize(){const r=await lab.run<Trace>('case-trace','case_trace',{...args(),sql:answer.value});if(r)trace.value=r;}
async function grade(){const r=await lab.run<Wire<CaseGrade>>('case-grade','case_grade',{...args(),sql:answer.value});if(r){grading.value=r;p.value.task=selected.value;if(r.status==='passed'&&!p.value.completed.includes(selected.value))p.value.completed.push(selected.value);changed();}}
function reproductionAnswer(){p.value.answers.reproduce=JSON.stringify({actual:actual.value,counter:counter.value,cause:cause.value});lab.invalidateJobs(['case-grade']);grading.value=undefined;changed();}
async function reproduce(){const r=await lab.run<{source:string,simulation:Simulation}>('case-simulation','case_reproduction',args());if(r)simulation.value=r;}
async function validate(mysql=false){const r=await lab.run<Wire<RepairValidation>>('case-repair',mysql?'case_repair_mysql':'case_repair',{...args(),strategy:strategy.value});if(r){repair.value=r;if(r.status==='passed'){if(mysql)p.value.mysql_strategy=r.strategy;else{p.value.model_strategy=r.strategy;if(!p.value.completed.includes('repair'))p.value.completed.push('repair');}changed();}}}
function pin(){if(!result.value)return;const card={id:crypto.randomUUID(),task:selected.value,sql:executedSql.value,table:{...result.value.table,rows:result.value.table.rows.slice(0,200),truncated:result.value.table.rows.length>200},case_version:spec.value!.version,seed:p.value.seed,snapshot:result.value.snapshot,note:'',hypothesis:'',links:[] as string[]};const size=(v:unknown)=>new TextEncoder().encode(JSON.stringify(v)).length;if(p.value.evidence.length>=20||size(card)>256*1024||size([...p.value.evidence,card])>4*1024*1024){lab.fail('证据板上限为 20 张卡、每卡 200 行 / 256 KiB、总计 4 MiB。请选择较少输出列后重新查询。');return}p.value.evidence.push(card);changed();}
function remove(id:string){p.value.evidence=p.value.evidence.filter(c=>c.id!==id);for(const c of p.value.evidence)c.links=c.links.filter(link=>link!==id);changed();}
async function rerun(id:string){const card=p.value.evidence.find(c=>c.id===id);if(!card)return;if(card.case_version!==spec.value?.version||card.seed!==p.value.seed){lab.fail('历史证据需要在当前案件版本重新查询并固定');return}selected.value=card.task;answer.value=card.sql;await run();}
async function close(){const r=await lab.run<Wire<CaseGrade>>('case-close','case_close',{...args(),progress:JSON.parse(JSON.stringify(p.value))});if(r){grading.value=r;if(r.status==='passed'){p.value.closed=true;lab.markDirty();}}}
async function preview(name:string){const sql=`SELECT * FROM "${name.replaceAll('"','""')}" LIMIT 100`;const r=await lab.run<{table:Table,snapshot:string}>('case-query','case_query',{...args(),sql});if(r){result.value=r;executedSql.value=sql;}}
async function report(){await exportText(`# ${spec.value?.title}\n\n案件版本：${p.value.version}；种子：${p.value.seed}\n\n状态：${p.value.closed?'已结案':'调查中'}\n\n模型策略：${p.value.model_strategy||'未验证'}；MySQL 策略：${p.value.mysql_strategy||'未实测'}\n\n`+p.value.evidence.map(c=>`## ${c.task}\n\n${c.note}\n\n来源：${c.snapshot}\n\n\`\`\`sql\n${c.sql}\n\`\`\`\n\n${markdownTable(c.table)}`).join('\n\n'),'选课事故调查报告.md');}
</script>
<template><div v-if="spec" class="lab-page case-page"><header class="page-heading"><div><span class="eyebrow">CASE 01 · OFFLINE INVESTIGATION</span><h1>{{spec.title}}</h1><p>{{spec.briefing}}</p></div><button @click="report().catch(lab.fail)">导出案件报告</button></header><div v-if="stale" class="notice warning">当前保存的是历史案件版本，证据会保留。<button @click="fresh">开始当前版本</button></div><nav class="case-tasks"><button v-for="t in spec.tasks" :key="t.id" :data-testid="`case-task-${t.id}`" :class="{active:selected===t.id}" @click="selected=t.id">{{p.completed.includes(t.id)?'✓ ':''}}{{t.title}}</button></nav><section v-if="task&&!stale" class="case-work"><h2>{{task.title}}</h2><p>{{task.prompt}}</p><div class="toolbar"><span>只读预览前 100 行：</span><button v-for="r in schema.relations" :key="r.name" @click="preview(r.name)">{{r.name}}</button></div><template v-if="['capacity','requests','timeline'].includes(selected)"><div class="answer-editor"><SqlEditor :id="`case-${spec.id}-${p.seed}-${selected}`" v-model="answer" :schema="schema" :theme="theme" @run="grade"/></div><div class="toolbar"><button class="primary" :disabled="!!lab.jobs['case-grade']" @click="grade">提交证据查询</button><button :disabled="!!lab.jobs['case-query']" @click="run">只读试运行</button><button @click="visualize">生成查询过程</button><button :disabled="!result" @click="pin">固定查询证据</button></div></template><template v-else-if="selected==='reproduce'"><PredictionCheckpoint v-if="showPrediction&&lab.workspace?.learning.mode!=='free'" id="oversubscription" @skip="showPrediction=false"/><button class="primary" @click="reproduce">回放两笔请求的读写与提交</button><SchedulePlayback v-if="simulation" :source="simulation.source" :result="simulation.simulation"/><div class="structured-answer"><label>实际成功人数<input v-model.number="actual" type="number" @input="reproductionAnswer"></label><label>计数器值<input v-model.number="counter" type="number" @input="reproductionAnswer"></label><label>原因<select v-model="cause" @change="reproductionAnswer"><option value="">请选择</option><option value="stale_read">两笔请求基于同一旧值检查，并覆盖写入</option><option value="duplicate_name">同名学生被当成同一个人</option><option value="null_count">NULL 被重复计数</option></select></label><button @click="grade">验证复现结论</button></div></template><template v-else><label>修复策略 <select v-model="strategy" @change="lab.invalidateJobs(['case-repair']);repair=undefined"><option value="naive">原方案：先读后覆盖写入</option><option value="unique_only">单独增加唯一约束</option><option value="row_lock">课程行锁：锁定后检查并写入</option><option value="conditional_update">原子条件更新：还有容量才预留</option></select></label><div class="toolbar"><button class="primary" @click="validate(false)">枚举离线模型</button><button @click="emit('connect')">连接 MySQL</button><button @click="validate(true)">真实 MySQL 拓展验证</button><button @click="lab.page='transactions'">自由双会话实验</button></div><details><summary>查看可运行的 MySQL 修复模板</summary><pre class="repair-templates">{{templates}}</pre><button @click="exportText(templates,'选课修复.mysql.sql').catch(lab.fail)">导出 SQL 模板</button></details><p>离线模型限定两个请求。真实验证使用新建的临时 MySQL 数据库，结束后清理；自定义 SQL 请在自由实验中记录。</p><div v-if="repair" class="grade-card" :class="repair.status"><strong>{{repair.mode==='mysql'?'MySQL 实测':'有限模型'}} · {{repair.status}}</strong><p>{{repair.message}}</p><table class="result-table"><thead><tr><th>场景</th><th>人数 / 计数</th><th>交错数</th><th>结果</th></tr></thead><tbody><tr v-for="s in repair.scenarios" :key="s.name"><td>{{s.name}}</td><td>{{s.actual}} / {{s.counter}}</td><td>{{s.schedules}}</td><td>{{s.passed?'通过':'不通过'}}</td></tr></tbody></table></div></template><div v-if="grading" class="grade-card" :class="grading.status" role="status"><strong>{{grading.status}}</strong><p>{{grading.message}}</p><ResultTable v-if="grading.expected" :table="grading.expected" :diff-rows="grading.diff?.expected" title="公开数据期望结果"/><ResultTable v-if="grading.actual" :table="grading.actual" :diff-rows="grading.diff?.actual" title="公开数据实际结果"/></div><ResultTable v-if="result" :table="result.table" title="冻结调查结果"/><TraceView v-if="trace" :trace="trace"/></section><section class="evidence-board"><h2>调查证据板 · {{p.evidence.length}} / 20</h2><p>把容量、异常请求与事件日志的查询固定到这里，并关联它们支持的根因。结案会重新执行 SQL 核验，不依赖卡片上的通过标记。</p><article v-for="card in p.evidence" :key="card.id" class="evidence-card"><h3>{{spec.tasks.find(t=>t.id===card.task)?.title??card.task}}</h3><small>{{card.snapshot}} · {{card.table.truncated?'节选前 200 行':'固定结果'}}{{card.case_version!==spec.version?' · 历史版本':''}}</small><pre>{{card.sql}}</pre><label>调查备注<input v-model="card.note" maxlength="4000" @input="changed"></label><label>支持的根因<select v-model="card.hypothesis" @change="changed"><option value="">尚未关联</option><option value="stale_read">读取旧计数后覆盖写入</option><option value="duplicate_name">同名学生</option><option value="null_count">NULL 计数</option></select></label><label>关联证据<select multiple v-model="card.links" @change="changed"><option v-for="other in p.evidence.filter(e=>e.id!==card.id)" :key="other.id" :value="other.id">{{other.task}} · {{other.note||other.id.slice(0,6)}}</option></select></label><details><summary>查看固定的类型化结果</summary><ResultTable :table="card.table" compact/></details><div class="toolbar"><button @click="rerun(card.id)">重新执行</button><button @click="remove(card.id)">删除卡片</button></div></article></section><section class="case-conclusion"><h2>结案核验</h2><label>根因<select v-model="p.cause" @change="changed"><option value="">请选择</option><option value="stale_read">两笔请求基于同一旧值检查，并覆盖写入</option><option value="duplicate_name">同名学生</option></select></label><p>模型：{{p.model_strategy||'未通过'}} · MySQL：{{p.mysql_strategy||'未实测（可选）'}}</p><button class="primary" :disabled="stale||!!lab.jobs['case-close']" @click="close">重新核验证据并结案</button><strong v-if="p.closed" role="status">✓ 案件已结案</strong></section></div><div v-else class="empty">正在加载案件…</div></template>
